import heapq
import random
import sys
sys.setrecursionlimit(1000000)


class Node:
    __slots__ = ('val', 'l', 'r', 'dist')

    def __init__(self, val):
        self.val = val
        self.l = None
        self.r = None
        self.dist = 0   # 外节点 dist=0，空节点视为 -1


def _d(x):
    return -1 if x is None else x.dist


def merge(x, y):
    """合并两棵左偏树（小根堆），返回新根。O(log n + log m)"""
    if x is None:
        return y
    if y is None:
        return x
    if x.val > y.val:
        x, y = y, x
    x.r = merge(x.r, y)
    if _d(x.l) < _d(x.r):
        x.l, x.r = x.r, x.l
    x.dist = _d(x.r) + 1
    return x


def insert(root, val):
    return merge(root, Node(val))


def pop_min(root):
    """删除并返回堆顶。返回 (新根, 原堆顶值)；空堆返回 (None, None)"""
    if root is None:
        return None, None
    return merge(root.l, root.r), root.val


if __name__ == '__main__':
    # 与 heapq 交叉验证（随机操作序列）
    random.seed(1)
    h = None
    ref = []
    for _ in range(5000):
        op = random.random()
        if op < 0.5 or not ref:
            v = random.randint(0, 100000)
            h = insert(h, v)
            heapq.heappush(ref, v)
        else:
            h, m = pop_min(h)
            r = heapq.heappop(ref)
            assert m == r, (m, r)
        if h is None:
            assert not ref
    # 双堆合并验证
    h1 = h2 = None
    r1, r2 = [], []
    for v in [3, 1, 4, 1, 5, 9, 2, 6]:
        h1 = insert(h1, v); r1.append(v)
    for v in [7, 0, 8, 5, 2]:
        h2 = insert(h2, v); r2.append(v)
    h = merge(h1, h2)
    r = sorted(r1 + r2)
    out = []
    while h is not None:
        h, m = pop_min(h)
        out.append(m)
    assert out == r, (out, r)
    print('leftist tree: All tests passed.')
